CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE IF NOT EXISTS physics_textbook (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  text        text,
  metadata    jsonb,
  embedding   vector(1536)
);

CREATE INDEX IF NOT EXISTS physics_textbook_embedding_idx
  ON physics_textbook USING ivfflat (embedding vector_cosine_ops) WITH (lists = 100);

CREATE OR REPLACE FUNCTION match_documents (
  query_embedding vector(1536),
  match_count int DEFAULT 5,
  filter jsonb DEFAULT '{}'
) RETURNS TABLE (
  id uuid, text text, metadata jsonb, similarity float
) LANGUAGE plpgsql AS $$
BEGIN
  RETURN QUERY
  SELECT t.id, t.text, t.metadata,
         1 - (t.embedding <=> query_embedding) AS similarity
  FROM physics_textbook t
  WHERE t.metadata @> filter
  ORDER BY t.embedding <=> query_embedding
  LIMIT match_count;
END;
$$;

