// داده‌ها را مستقیم از نود فرم می‌خوانیم (نود Postgres باینری را پاس نمی‌دهد)
const formItems = $('On form submission').all();
const out = [];

// تبدیل ارقام فارسی به انگلیسی
const faToEn = (s) =>
  String(s || '').replace(/[۰-۹]/g, (d) => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));

function detectGrade(raw) {
  if (!raw) return null;
  const text = faToEn(raw);

  // ترتیب مهم است: «دهم» زیررشتهٔ «یازدهم» و «دوازدهم» است
  if (text.includes('دوازدهم')) return 'دوازدهم';
  if (text.includes('یازدهم'))  return 'یازدهم';
  if (text.includes('دهم'))     return 'دهم';

  // اول اعداد دورقمی (10/11/12) تا «12» اشتباهاً «1» یا «2» تفسیر نشود
  if (/(?:^|\D)12(?:\D|$)/.test(text)) return 'دوازدهم';
  if (/(?:^|\D)11(?:\D|$)/.test(text)) return 'یازدهم';
  if (/(?:^|\D)10(?:\D|$)/.test(text)) return 'دهم';

  // سپس تک‌رقمی (فیزیک 1 = دهم و ...)
  if (/(?:^|\D)3(?:\D|$)/.test(text)) return 'دوازدهم';
  if (/(?:^|\D)2(?:\D|$)/.test(text)) return 'یازدهم';
  if (/(?:^|\D)1(?:\D|$)/.test(text)) return 'دهم';

  return null;
}

for (const item of formItems) {
  // پیدا کردن کلید واقعی باینری (فرم آن را «فایل_pdf_کتاب» می‌سازد نه data)
  const binKeys = Object.keys(item.binary || {});
  const binKey  = binKeys.includes('data') ? 'data' : binKeys[0];
  const file    = binKey ? item.binary[binKey] : null;
  const fileName = file?.fileName || 'unknown.pdf';

  // اولویت ۱: پاسخ کاربر در فرم — اولویت ۲: نام فایل
  const grade =
    detectGrade(item.json['کتاب فیزیک کلاس چندم؟']) ||
    detectGrade(fileName) ||
    'نامشخص';

  out.push({
    json: {
      fileName,
      grade,
      book: `فیزیک ${grade}`,
      source: 'کتاب درسی',
    },
    // باینری را زیر کلید استاندارد data می‌گذاریم تا Document Loader آن را ببیند
    binary: file ? { data: file } : {},
  });
}

return out;
